<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../app/helpers.php';require_login();$pdo=db();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to){$from=date('Y-m-01');$to=date('Y-m-d');}
$st=$pdo->prepare("SELECT COUNT(*) order_count,COALESCE(SUM(total_amount),0) revenue FROM orders WHERE status='completed' AND DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$summary=$st->fetch();
$st=$pdo->prepare("SELECT p.sku,p.name,SUM(oi.quantity) qty,SUM(oi.line_total) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN products p ON p.id=oi.product_id WHERE o.status='completed' AND DATE(o.created_at) BETWEEN ? AND ? GROUP BY p.id,p.sku,p.name ORDER BY qty DESC LIMIT 10");$st->execute([$from,$to]);$best=$st->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="stockpro-report.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['SKU','Sản phẩm','Số lượng đã bán','Doanh thu']);foreach($best as $r)fputcsv($out,[$r['sku'],$r['name'],$r['qty'],$r['revenue']]);fclose($out);exit;}
$pageTitle='Báo cáo';require __DIR__.'/../app/layout/header.php';?>
<div class="page-heading mb-3"><div><h1 class="h3">Báo cáo bán hàng</h1><p class="text-secondary mb-0">Thống kê theo khoảng ngày đã chọn.</p></div></div><div class="card mb-4"><div class="card-body"><form class="row g-3 align-items-end"><div class="col-12 col-md-4"><label class="form-label">Từ ngày</label><input type="date" name="from" value="<?=e($from)?>" class="form-control" required></div><div class="col-12 col-md-4"><label class="form-label">Đến ngày</label><input type="date" name="to" value="<?=e($to)?>" class="form-control" required></div><div class="col-auto"><button class="btn btn-primary">Lọc</button> <a class="btn btn-outline-success" href="?from=<?=e($from)?>&to=<?=e($to)?>&export=csv">Xuất CSV</a></div></form></div></div><div class="row g-3 mb-4"><div class="col-12 col-md-6"><div class="card"><div class="card-body"><div class="muted-label">Số đơn hoàn tất</div><div class="stat-value"><?= (int)$summary['order_count'] ?></div></div></div></div><div class="col-12 col-md-6"><div class="card"><div class="card-body"><div class="muted-label">Doanh thu</div><div class="stat-value"><?=money($summary['revenue'])?></div></div></div></div></div><div class="card"><div class="card-body"><h2 class="h5">Top 10 sản phẩm bán chạy</h2><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>SKU</th><th>Sản phẩm</th><th>Số lượng</th><th>Doanh thu</th></tr></thead><tbody><?php foreach($best as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['sku'])?></td><td><?=e($r['name'])?></td><td><?=(int)$r['qty']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach;?><?php if(!$best):?><tr><td colspan="5" class="text-secondary">Không có dữ liệu trong khoảng ngày này.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../app/layout/footer.php';?>
